SELECT *
FROM market_daily_price
WHERE asset_code = #{assetCode}
  AND asset_type = #{assetType}
  AND trade_date BETWEEN #{fromDate} AND #{toDate}
ORDER BY trade_date

SELECT *
FROM market_daily_price
WHERE asset_type = #{assetType}
  AND trade_date = #{tradeDate}
ORDER BY market_cap DESC NULLS LAST, asset_code

SELECT COUNT(*)
FROM market_daily_price
WHERE asset_type = #{assetType}
  AND trade_date = #{tradeDate}

SELECT *
FROM market_daily_price
WHERE asset_type = #{assetType}
  AND trade_date BETWEEN #{fromDate} AND #{toDate}
ORDER BY trade_date, market_cap DESC NULLS LAST, asset_code
LIMIT 1
